// Respuesta del Banco Mundial: un array [metadatos, registros]
// En n8n llega como UN item cuyo json es ese array (o el body dentro de un wrapper).
const raw = $input.first().json;
const datos = Array.isArray(raw) ? raw : (raw.body ? raw.body : raw.data ? raw.data : null);
if (!datos || !Array.isArray(datos)) {
  throw new Error('Respuesta inesperada del Banco Mundial. Mirá la SALIDA del nodo HTTP Request y ajustá esta primera línea (debug parte del ejercicio).');
}
const registros = datos[1];
// Agregados del Banco Mundial (región 'NA', verificado 2026-10-02 sobre /v2/country)
const AGG = new Set(['AFE','AFR','AFW','ARB','BEA','BEC','BHI','BLA','BMN','BSS','CAA','CEA','CEB','CEU','CLA','CME','CSA','CSS','DEA','DEC','DLA','DMN','DNS','DSA','DSF','DSS','EAP','EAR','EAS','ECA','ECS','EMU','EUU','FXS','HIC','HPC','IBB','IBD','IBT','IDA','IDB','IDX','INX','LAC','LCN','LDC','LIC','LMC','LMY','LTE','MDE','MEA','MIC','MNA','NAC','NAF','NRS','NXS','OED','OSS','PRE','PSS','PST','RRS','SAS','SSA','SSF','SST','SXZ','TEA','TEC','TLA','TMN','TSA','TSS','UMC','WLD','XZN']);
const filas = registros.map(r => ({
  json: {
    codigo_iso3: r.countryiso3code || '',
    nombre_pais: (r.country && r.country.value) || '',
    anio: parseInt(r.date, 10),
    poblacion: r.value,
    fuente: 'Banco Mundial'
  }
}));
return filas.filter(f => f.json.codigo_iso3 && !AGG.has(f.json.codigo_iso3) && f.json.poblacion !== null);

// Las 3 paginas de REST Countries llegan como 3 items;
// cada uno trae data.objects (JSON:API). Campos verificados el 2026-10-02:
// names.common, codes.alpha_3, capitals[0].name, region, population
const salidas = $input.all().map(i => i.json);
const filas = [];
for (const s of salidas) {
  const objs = (s && s.data && s.data.objects) ? s.data.objects : (Array.isArray(s) ? s : []);
  for (const c of objs) {
    filas.push({ json: {
      codigo_iso3: c.codes && c.codes.alpha_3 ? c.codes.alpha_3 : '',
      nombre_pais: c.names && c.names.common ? c.names.common : '',
      anio: 2026, // population de v5 es "al momento"
      poblacion: typeof c.population === 'number' ? c.population : null,
      fuente: 'REST Countries'
    }});
  }
}
return filas.filter(f => f.json.codigo_iso3 && f.json.nombre_pais && f.json.poblacion !== null);
